-- CAB-0009: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin if exists(select 1 from public.entities where slug='prs' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='gabungan-parti-sarawak'))) then raise exception 'CAB-0009: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party', parent.id,'prs','Parti Rakyat Sarawak','PRS','government','A component party of Gabungan Parti Sarawak (GPS).','2026-11-09','[{"label": "SPR · registered party symbols", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}, {"label": "PRS · 2025–2028 leadership", "url": "https://www.bernama.com/en/news.php?id=2480720"}]'::jsonb from public.entities parent where parent.slug='gabungan-parti-sarawak' and parent.type='alliance' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'CAB-0009: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='prs' and type='party') then raise exception 'CAB-0009: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='gabungan-parti-sarawak' and type='alliance') then raise exception 'CAB-0009: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('fadhlina-sidek','aaron-ago-dagang') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0009: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('nibong tebal','kanowit') and slug not in ('fadhlina-sidek','aaron-ago-dagang')) then raise exception 'CAB-0009: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0009:%' and (m.source_type <> 'editorial' or e.slug not in ('fadhlina-sidek','aaron-ago-dagang') or m.import_key not like 'CAB-0009:' || e.slug || ':%')) then raise exception 'CAB-0009: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'fadhlina-sidek','Fadhlina Sidek','government','Minister of Education','Nibong Tebal','Pulau Pinang','Fadhlina Sidek is Minister of Education. She represents Nibong Tebal, Pulau Pinang, in the Dewan Rakyat. She is a member of Parti Keadilan Rakyat (PKR).','https://www.moe.gov.my/','/portraits/fadhlina-sidek.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P047.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Nibong Tebal", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4086"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'aaron-ago-dagang','Aaron Ago Dagang','government','Minister of National Unity','Kanowit','Sarawak','Aaron Ago Dagang is Minister of National Unity. He represents Kanowit, Sarawak, in the Dewan Rakyat. He is a member of Parti Rakyat Sarawak (PRS).','https://www.perpaduan.gov.my/','/portraits/aaron-ago-dagang.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P210.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Kanowit", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4249"}, {"label": "PRS · 2025–2028 leadership", "url": "https://www.bernama.com/en/news.php?id=2480720"}]'::jsonb from public.entities parent where parent.slug='prs' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('fadhlina-sidek','aaron-ago-dagang') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0009: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0009:fadhlina-sidek:sabah-curriculum-2027','Include Sabah’s identity in the new Year One and Form One curriculum','Education',null,null,'2027-12-31','2026-09-11','https://www.bernama.com/radio/news.php?id=2606122',null,null,'Fadhlina said elements of Sabah’s identity would be included in the new Year One and Form One curriculum from the 2027 academic session.','The statement establishes an agreed curriculum commitment following the MA63 implementation meeting. Delivery in the 2027 school session was not verified. The year-end date marks the target year, not a promised exact day.','2026-11-09','editorial',false from public.entities e where e.slug='fadhlina-sidek' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0009:fadhlina-sidek:sabah-416-school-replacements','Fully replace 416 identified dilapidated schools in Sabah','Education','in_progress',59,null,'2026-09-11','https://www.bernama.com/radio/news.php?id=2606122','2026-09-11','https://www.bernama.com/radio/news.php?id=2606122','Fadhlina described a full-replacement programme covering 416 identified dilapidated schools in Sabah.','As reported on 11 September 2026, 245 were fully rebuilt and 63 were under construction. The bar is 245 ÷ 416 × 100 = 58.89%, rounded to 59%. It counts completed school replacements, not expenditure or the later construction stages. No overall deadline was established.','2026-11-09','editorial',false from public.entities e where e.slug='fadhlina-sidek' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0009:aaron-ago-dagang:mediators-1280-2030','Produce 1,280 certified community mediators by 2030','Social welfare',null,null,'2030-12-31','2026-08-03','https://www.bernama.com/en/general/news.php?id=2589635',null,null,'Aaron set a ministry target of producing 1,280 certified community mediators by 2030 to strengthen local dispute resolution.','The statement establishes the target. A comparable certified-mediator total and target-specific outcome were not verified in this pass. Planned mediation centres are not counted as certified people; status and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='aaron-ago-dagang' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0009:aaron-ago-dagang:active-krt-grant-2027','Raise the annual Active KRT Grant to RM10,000 from 2027','Social welfare',null,null,'2027-12-31','2026-10-12','https://www.bernama.com/en/general/news.php?id=2619248',null,null,'Aaron announced that the annual grant for active Rukun Tetangga areas would rise from RM6,000 to RM10,000 starting in 2027.','This is a future grant-rate commitment. The Budget 2027 announcement is not evidence that recipients have received the higher grant. Outcome and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='aaron-ago-dagang' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

